// Des: Tests for ru-tier-ladd: M3 gate on the mock vendor
// Flo: mock site + mock vendor > fetch > assert tiers, calls, spend, errors
// I/O: mock responses > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const ladd = @import("ru-tier-ladd.zig"); const inde = @import("st-page-inde.zig"); const spen = @import("ru-spen-guar.zig"); const kill = @import("ru-kill-swit.zig"); const vmock = @import("nt-vend-mock.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Rig = struct { tmpz: std.testing.TmpDir, srv: mock.Mock, vmk: vmock.Mock, dirz: []u8, dbzz: sqli.Db, aren: std.heap.ArenaAllocator, lad: ladd.Ladd,
pub fn up(self: *Rig, conf: cfgz.Conf, rules: []const vmock.Rule) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); try self.srv.start(std.testing.io); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.vmk = vmock.Mock.init(allo); self.vmk.rules = rules; self.lad = .{ .gpaz = allo, .iozz = std.testing.io, .conf = conf, .dbzz = &self.dbzz, .dirz = self.dirz, .back = self.vmk.backend(), .priv = true }; }
pub fn down(self: *Rig) void { self.vmk.deinit(); self.aren.deinit(); self.dbzz.close(); self.srv.halt(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn go(self: *Rig, path: []const u8) !@import("ru-page-fetc.zig").Outc { var buf: [64]u8 = undefined; return ladd.laddFetc(&self.lad, self.aren.allocator(), self.srv.urlOf(&buf, path)); } };
fn rich() cfgz.Conf { var conf: cfgz.Conf = .{}; conf.vend_free_cred = .{ .deco = 100, .zenr = 100, .brig = 100 }; return conf; }
test "friendly host: T1 only, no vendor call, no spend" { var rig: Rig = undefined; try rig.up(rich(), &.{}); defer rig.down(); const out = try rig.go("/p1"); try std.testing.expectEqualStrings("new", out.stat); try std.testing.expectEqual(@as(i64, 1), out.tier); try std.testing.expectEqual(@as(usize, 0), rig.vmk.calls.items.len); try std.testing.expectEqual(@as(i64, 0), try spen.spenTota(&rig.dbzz, std.Io.Clock.real.now(std.testing.io).toMilliseconds())); }
test "block page escalates plain -> render, spends free credits, remembers the tier" { var rig: Rig = undefined; try rig.up(rich(), &.{.{ .has = "blockp", .minm = .rend }}); defer rig.down(); const out = try rig.go("/blockp"); try std.testing.expectEqualStrings("new", out.stat); try std.testing.expectEqual(@as(i64, 3), out.tier); try std.testing.expectEqualStrings("deco", out.vend); try std.testing.expectEqual(@as(usize, 2), rig.vmk.calls.items.len); try std.testing.expectEqual(@as(u32, 2), out.cred); try std.testing.expectEqual(@as(u64, 0), out.micr); const now = std.Io.Clock.real.now(std.testing.io).toMilliseconds(); try std.testing.expectEqual(@as(i64, 3), try spen.spenUsed(&rig.dbzz, .deco, @intCast(now))); const again = try rig.go("/blockp?x=1"); try std.testing.expectEqualStrings("new", again.stat); try std.testing.expectEqual(@as(usize, 3), rig.vmk.calls.items.len); try std.testing.expectEqual(vmock.Mock.hits(&rig.vmk, .deco), 3); try std.testing.expectEqual(@as(@TypeOf(rig.vmk.calls.items[2].mode), .rend), rig.vmk.calls.items[2].mode); }
test "never retries a block on the same vendor and mode; exhausted ladder = Blocked" { var rig: Rig = undefined; try rig.up(rich(), &.{.{ .has = "blockp", .minm = .prem, .body = "x" }}); defer rig.down(); const out = try rig.go("/blockp"); try std.testing.expectEqual(@as(i64, 4), out.tier); try std.testing.expectEqual(@as(usize, 3), rig.vmk.calls.items.len); var seen = std.AutoHashMap(u32, void).init(allo); defer seen.deinit(); for (rig.vmk.calls.items) |call| { const key: u32 = @as(u32, @backingInt(call.vend)) * 10 + @backingInt(call.mode); try std.testing.expect(!seen.contains(key)); try seen.put(key, {}); } var rig2: Rig = undefined; try rig2.up(rich(), &.{.{ .has = "blockp", .minm = .prem }}); defer rig2.down(); rig2.vmk.rules = &.{.{ .has = "blockp", .minm = .prem, .body = "" }}; rig2.lad.conf.vend_orde = &.{"deco"}; const blk = rig2.go("/blockp"); try std.testing.expectError(error.Blocked, blk); try std.testing.expectEqual(@as(usize, 3), rig2.vmk.calls.items.len); }
test "vendor outage falls back to the next vendor in the row" { var rig: Rig = undefined; try rig.up(rich(), &.{}); defer rig.down(); rig.vmk.down[0] = true; const out = try rig.go("/e403"); try std.testing.expectEqualStrings("zenr", out.vend); try std.testing.expectEqual(@as(usize, 2), rig.vmk.calls.items.len); }
test "cap stops spend: no free credits and no go means OverCap, zero vendor calls" { var rig: Rig = undefined; try rig.up(.{}, &.{}); defer rig.down(); try std.testing.expectError(error.OverCap, rig.go("/e403")); try std.testing.expectEqual(@as(usize, 0), rig.vmk.calls.items.len); }
test "paid spend needs go and stays under the cap" { var conf: cfgz.Conf = .{}; conf.capz_usdz_mont = 0.003; conf.vend_orde = &.{"zenr"}; var rig: Rig = undefined; try rig.up(conf, &.{}); defer rig.down(); try std.testing.expectError(error.OverCap, rig.go("/e403")); rig.lad.go = true; const out = try rig.go("/e403"); try std.testing.expectEqual(@as(u64, 1000), out.micr); const now = std.Io.Clock.real.now(std.testing.io).toMilliseconds(); try std.testing.expectEqual(@as(i64, 1000), try spen.spenTota(&rig.dbzz, @intCast(now))); var cnt: usize = 0; while (cnt < 5) : (cnt += 1) { var pbuf: [32]u8 = undefined; var bb: [64]u8 = undefined; const urlz = try std.fmt.bufPrint(&pbuf, "/e403?n={d}", .{cnt}); const full = rig.srv.urlOf(&bb, urlz); _ = ladd.laddFetc(&rig.lad, rig.aren.allocator(), full) catch {}; } try std.testing.expect(try spen.spenTota(&rig.dbzz, @intCast(now)) <= 3000); }
test "kill switch halts all vendor calls at once" { var rig: Rig = undefined; try rig.up(rich(), &.{}); defer rig.down(); try kill.killSet(&rig.dbzz, true); try std.testing.expectError(error.KillOn, rig.go("/e403")); try std.testing.expectEqual(@as(usize, 0), rig.vmk.calls.items.len); const free = try rig.go("/p1"); try std.testing.expectEqualStrings("new", free.stat); }
test "own TLS/network failure that is not NeedVendor is returned, not paid around" { var rig: Rig = undefined; try rig.up(rich(), &.{}); defer rig.down(); try std.testing.expectError(error.NotText, rig.go("/img")); try std.testing.expectEqual(@as(usize, 0), rig.vmk.calls.items.len); }
test "a friendly page on a host that blocked before still goes out free (no credits)" { var rig: Rig = undefined; try rig.up(rich(), &.{.{ .has = "blockp", .minm = .rend }}); defer rig.down(); _ = try rig.go("/blockp"); const calls = rig.vmk.calls.items.len; const out = try rig.go("/p1"); try std.testing.expectEqual(@as(i64, 1), out.tier); try std.testing.expectEqual(calls, rig.vmk.calls.items.len); }
test "host whose own GET failed 3 times in a row goes straight to the vendor, no wasted request" { var rig: Rig = undefined; try rig.up(rich(), &.{}); defer rig.down(); var cnt: usize = 0; while (cnt < 3) : (cnt += 1) { var pbuf: [32]u8 = undefined; const out = try rig.go(try std.fmt.bufPrint(&pbuf, "/e403?n={d}", .{cnt})); try std.testing.expect(out.tier >= 2); } const before = rig.srv.hits.load(.monotonic); const four = try rig.go("/e403?n=9"); try std.testing.expect(four.tier >= 2); try std.testing.expectEqual(before, rig.srv.hits.load(.monotonic)); }
